<article class="news-card"><a class="news-card-image" href="<?= url('/noticia/'.$post['slug']) ?>"><img src="<?= e(post_image($post['image'])) ?>" alt="<?= e($post['title']) ?>" loading="lazy"></a><div class="news-card-copy"><small><?= e($post['category_name']) ?></small><h3><a href="<?= url('/noticia/'.$post['slug']) ?>"><?= e($post['title']) ?></a></h3><?php if (!empty($post['excerpt'])): ?><p><?= e($post['excerpt']) ?></p><?php endif; ?><time datetime="<?= e($post['published_at']) ?>"><?= e(date_es($post['published_at'])) ?></time><a class="more" href="<?= url('/noticia/'.$post['slug']) ?>">Leer noticia <span>→</span></a></div></article>
